);

CREATE TABLE IF NOT EXISTS course_catalog (
  id TEXT PRIMARY KEY,
  uuid TEXT NOT NULL UNIQUE,
  tenant_id TEXT NOT NULL,
  organization_id TEXT NOT NULL DEFAULT '0',
  course_code TEXT NOT NULL,
  category_id TEXT,
  primary_instructor_id TEXT,
  title TEXT NOT NULL,
  subtitle TEXT,
  summary TEXT,
  description TEXT,
  learning_objectives_json TEXT NOT NULL DEFAULT '[]',
  target_audience_json TEXT NOT NULL DEFAULT '[]',
  prerequisites_json TEXT NOT NULL DEFAULT '[]',
  difficulty_level TEXT,
  language_code TEXT,
  cover_resource_snapshot TEXT,
  intro_video_resource_ref_id TEXT,
  tags_json TEXT NOT NULL DEFAULT '[]',
  estimated_duration_seconds INTEGER NOT NULL DEFAULT 0,
  lesson_count_snapshot INTEGER NOT NULL DEFAULT 0,
  student_count_snapshot INTEGER NOT NULL DEFAULT 0,
  rating_score_snapshot TEXT NOT NULL DEFAULT '0',
  rating_count_snapshot INTEGER NOT NULL DEFAULT 0,
  external_source_id TEXT,
  body_content TEXT,
  price_amount TEXT,
  original_price_amount TEXT,
  currency TEXT,
  is_free INTEGER NOT NULL DEFAULT 1,
  is_collection INTEGER NOT NULL DEFAULT 0,
  -- Content shape owned by the course center:
  --   standard   -> chapter (course_section) + lesson curriculum
  --   column     -> serialized column; lessons may be flat articles/videos
  --   collection -> ordered bundle of published courses (course_catalog_link)
  course_kind TEXT NOT NULL DEFAULT 'standard',
  -- UGC ownership. Official catalog content leaves this NULL.
  author_user_id TEXT,
  author_display_name TEXT,
  -- Review workflow. publish_status='reviewing' means the author submitted the
  -- current draft; review_note carries the operator's latest decision note so a
  -- rejected draft can be explained without a second table.
  review_note TEXT,
  submitted_at TEXT,
  reviewed_at TEXT,
  reviewed_by TEXT,
  review_round INTEGER NOT NULL DEFAULT 0,
  visibility TEXT NOT NULL DEFAULT 'tenant',
  publish_status TEXT NOT NULL DEFAULT 'draft',
  published_at TEXT,
  status TEXT NOT NULL,
  created_at TEXT NOT NULL,
  created_by TEXT,
  updated_at TEXT NOT NULL,
  updated_by TEXT,
  version INTEGER NOT NULL DEFAULT 0,
  deleted_at TEXT,
  deleted_by TEXT,
  UNIQUE (tenant_id, organization_id, course_code)
);

